(function(root){
const months={january:0,february:1,march:2,april:3,may:4,june:5,july:6,august:7,september:8,october:9,november:10,december:11};
function deadline(text){const pattern=/\b(?:application deadline|applications close|closing date|apply by|deadline)\s*(?:is|on|:|-)?\s*(\d{4}-\d{2}-\d{2}|\d{1,2}(?:st|nd|rd|th)?\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{4})\b/gi;let match,dates=[];while((match=pattern.exec(text||''))){const raw=match[1];let y,m,d;if(/^\d{4}-/.test(raw)){[y,m,d]=raw.split('-').map(Number);m--}else{const p=raw.replace(/(\d)(st|nd|rd|th)/i,'$1').split(/\s+/);d=Number(p[0]);m=months[p[1].toLowerCase()];y=Number(p[2])}const date=new Date(Date.UTC(y,m,d,23,59,59,999));if(date.getUTCFullYear()===y&&date.getUTCMonth()===m&&date.getUTCDate()===d)dates.push(date.toISOString())}return dates.sort()[0]||null}
function state(job,now=Date.now()){if(job.checkedAt&&now-new Date(job.checkedAt).getTime()>48*3600000)return {visible:false,reason:'unverified'};const closing=job.expiresAt||deadline(job.description);const end=closing?new Date(closing).getTime():NaN;if(Number.isFinite(end)&&end<now)return {visible:false,reason:'expired',closing};const posted=new Date(job.date).getTime();if(!job.confirmedActive&&Number.isFinite(posted)&&now-posted>45*86400000)return {visible:false,reason:'older',closing};return {visible:true,reason:'current',closing}}
root.JobFreshness={deadline,state};
})(globalThis);
